const e = $input.first().json;
const exec = e.execution || {};
const wf = e.workflow || {};
const last = exec.lastNodeExecuted;
const errObj = exec.error || {};
const payload = {
  workflow_name: wf.name || '(unknown)',
  workflow_id: wf.id || null,
  execution_id: exec.id || null,
  execution_url: exec.url || null,
  failed_node: last || '(unknown)',
  error_message: errObj.message || (errObj.stack || '').slice(0, 400) || '(no message)',
  metadata: { mode: exec.mode, retryOf: exec.retryOf || null },
};
return [{ json: payload }];
